 25→// ErrTrailNotFound is returned when a trail cannot be found.
 26→var ErrTrailNotFound = errors.New("trail not found")
 27→
 28→// Store provides CRUD operations for trail metadata on the entire/trails branch.
 29→type Store struct {
 30→	repo *git.Repository
 31→}
 32→
 33→// NewStore creates a new trail store backed by the given git repository.
 34→func NewStore(repo *git.Repository) *Store {
 35→	return &Store{repo: repo}
 36→}
 37→
 38→// EnsureBranch creates the entire/trails orphan branch if it doesn't exist.
 39→func (s *Store) EnsureBranch() error {
 40→	refName := plumbing.NewBranchReferenceName(paths.TrailsBranchName)
 41→	_, err := s.repo.Reference(refName, true)
 42→	if err == nil {
 43→		return nil // Branch already exists
 44→	}
 45→
 46→	// Create orphan branch with empty tree
 47→	emptyTreeHash, err := checkpoint.BuildTreeFromEntries(s.repo, make(map[string]object.TreeEntry))
 48→	if err != nil {
 49→		return fmt.Errorf("failed to build empty tree: %w", err)
 50→	}
 51→
 52→	authorName, authorEmail := checkpoint.GetGitAuthorFromRepo(s.repo)
 53→	commitHash, err := s.createCommit(emptyTreeHash, plumbing.ZeroHash, "Initialize trails branch", authorName, authorEmail)
 54→	if err != nil {
 55→		return fmt.Errorf("failed to create initial commit: %w", err)
 56→	}
 57→
 58→	newRef := plumbing.NewHashReference(refName, commitHash)
 59→	if err := s.repo.Storer.SetReference(newRef); err != nil {
 60→		return fmt.Errorf("failed to set branch reference: %w", err)
 61→	}
 62→	return nil
 63→}
 64→
 65→// Write writes trail metadata, discussion, and checkpoints to the entire/trails branch.
 66→// If checkpoints is nil, an empty checkpoints list is written.
 67→func (s *Store) Write(metadata *Metadata, discussion *Discussion, checkpoints *Checkpoints) error {
 68→	if metadata.TrailID.IsEmpty() {
 69→		return errors.New("trail ID is required")
 70→	}
 71→
 72→	if err := s.EnsureBranch(); err != nil {
 73→		return fmt.Errorf("failed to ensure trails branch: %w", err)
 74→	}
 75→
 76→	// Get current branch tree
 77→	ref, entries, err := s.getBranchEntries()
 78→	if err != nil {
 79→		return fmt.Errorf("failed to get branch entries: %w", err)
 80→	}
 81→
 82→	// Build sharded path
 83→	basePath := metadata.TrailID.Path() + "/"
 84→
 85→	// Create metadata blob
 86→	metadataJSON, err := json.MarshalIndent(metadata, "", "  ")
 87→	if err != nil {
 88→		return fmt.Errorf("failed to marshal metadata: %w", err)
 89→	}
 90→	metadataBlob, err := checkpoint.CreateBlobFromContent(s.repo, metadataJSON)
 91→	if err != nil {
 92→		return fmt.Errorf("failed to create metadata blob: %w", err)
 93→	}
 94→	entries[basePath+metadataFile] = object.TreeEntry{
 95→		Name: basePath + metadataFile,
 96→		Mode: filemode.Regular,
 97→		Hash: metadataBlob,
 98→	}
 99→
100→	// Create discussion blob
101→	if discussion == nil {
102→		discussion = &Discussion{Comments: []Comment{}}
103→	}
104→	discussionJSON, err := json.MarshalIndent(discussion, "", "  ")
105→	if err != nil {
106→		return fmt.Errorf("failed to marshal discussion: %w", err)
107→	}
108→	discussionBlob, err := checkpoint.CreateBlobFromContent(s.repo, discussionJSON)
109→	if err != nil {
110→		return fmt.Errorf("failed to create discussion blob: %w", err)
111→	}
112→	entries[basePath+discussionFile] = object.TreeEntry{
113→		Name: basePath + discussionFile,
114→		Mode: filemode.Regular,
115→		Hash: discussionBlob,
116→	}
117→
118→	// Create checkpoints blob
119→	if checkpoints == nil {
120→		checkpoints = &Checkpoints{Checkpoints: []CheckpointRef{}}
121→	}
122→	checkpointsJSON, err := json.MarshalIndent(checkpoints, "", "  ")
123→	if err != nil {
124→		return fmt.Errorf("failed to marshal checkpoints: %w", err)
125→	}
126→	checkpointsBlob, err := checkpoint.CreateBlobFromContent(s.repo, checkpointsJSON)
127→	if err != nil {
128→		return fmt.Errorf("failed to create checkpoints blob: %w", err)
129→	}
130→	entries[basePath+checkpointsFile] = object.TreeEntry{
131→		Name: basePath + checkpointsFile,
132→		Mode: filemode.Regular,
133→		Hash: checkpointsBlob,
134→	}
135→
136→	// Build tree and commit
137→	newTreeHash, err := checkpoint.BuildTreeFromEntries(s.repo, entries)
138→	if err != nil {
139→		return fmt.Errorf("failed to build tree: %w", err)
140→	}
141→
142→	authorName, authorEmail := checkpoint.GetGitAuthorFromRepo(s.repo)
143→	commitMsg := fmt.Sprintf("Trail: %s (%s)", metadata.Title, metadata.TrailID)
144→	commitHash, err := s.createCommit(newTreeHash, ref.Hash(), commitMsg, authorName, authorEmail)
145→	if err != nil {
146→		return fmt.Errorf("failed to create commit: %w", err)
147→	}
148→
149→	// Update branch ref
150→	newRef := plumbing.NewHashReference(plumbing.NewBranchReferenceName(paths.TrailsBranchName), commitHash)
151→	if err := s.repo.Storer.SetReference(newRef); err != nil {
152→		return fmt.Errorf("failed to update branch reference: %w", err)
153→	}
154→
155→	return nil
156→}
