220→// FindByBranch finds a trail for the given branch name.
221→// Returns (nil, nil) if no trail exists for the branch.
222→func (s *Store) FindByBranch(branchName string) (*Metadata, error) {
223→	trails, err := s.List()
224→	if err != nil {
225→		return nil, err
226→	}
227→
228→	for _, t := range trails {
229→		if t.Branch == branchName {
230→			return t, nil
231→		}
232→	}
233→	return nil, nil //nolint:nilnil // nil, nil means "not found" — callers check both
234→}
