236→// List returns all trail metadata from the entire/trails branch.
237→func (s *Store) List() ([]*Metadata, error) {
238→	tree, err := s.getBranchTree()
239→	if err != nil {
240→		// Branch doesn't exist yet — no trails
241→		return nil, nil //nolint:nilerr // Expected when no trails exist yet
242→	}
243→
244→	var trails []*Metadata
245→	entries := make(map[string]object.TreeEntry)
246→	if err := checkpoint.FlattenTree(s.repo, tree, "", entries); err != nil {
247→		return nil, fmt.Errorf("failed to flatten tree: %w", err)
248→	}
249→
250→	// Find all metadata.json files
251→	for path, entry := range entries {
252→		if !strings.HasSuffix(path, "/"+metadataFile) {
253→			continue
254→		}
255→
256→		blob, err := s.repo.BlobObject(entry.Hash)
257→		if err != nil {
258→			continue
259→		}
260→		reader, err := blob.Reader()
261→		if err != nil {
262→			continue
263→		}
264→
265→		var metadata Metadata
266→		decodeErr := json.NewDecoder(reader).Decode(&metadata)
267→		_ = reader.Close()
268→		if decodeErr != nil {
269→			continue
270→		}
271→
272→		trails = append(trails, &metadata)
273→	}
274→
275→	return trails, nil
276→}
