278→// Update updates an existing trail's metadata. It reads the current metadata,
279→// applies the provided update function, and writes it back.
280→func (s *Store) Update(trailID ID, updateFn func(*Metadata)) error {
281→	metadata, discussion, checkpoints, err := s.Read(trailID)
282→	if err != nil {
283→		return fmt.Errorf("failed to read trail for update: %w", err)
284→	}
285→
286→	updateFn(metadata)
287→	metadata.UpdatedAt = time.Now()
288→
289→	return s.Write(metadata, discussion, checkpoints)
290→}
