292→// AddCheckpoint prepends a checkpoint reference to a trail's checkpoints list (newest first).
293→func (s *Store) AddCheckpoint(trailID ID, ref CheckpointRef) error {
294→	metadata, discussion, checkpoints, err := s.Read(trailID)
295→	if err != nil {
296→		return fmt.Errorf("failed to read trail for checkpoint update: %w", err)
297→	}
298→
299→	if checkpoints == nil {
300→		checkpoints = &Checkpoints{Checkpoints: []CheckpointRef{}}
301→	}
302→
303→	// Prepend new ref (newest first) without always allocating a new slice.
304→	// Grow the slice by one, shift existing elements right, and insert at index 0.
305→	checkpoints.Checkpoints = append(checkpoints.Checkpoints, CheckpointRef{})
306→	copy(checkpoints.Checkpoints[1:], checkpoints.Checkpoints[:len(checkpoints.Checkpoints)-1])
307→	checkpoints.Checkpoints[0] = ref
308→
309→	return s.Write(metadata, discussion, checkpoints)
310→}
