312→// Delete removes a trail from the entire/trails branch.
313→func (s *Store) Delete(trailID ID) error {
314→	ref, entries, err := s.getBranchEntries()
315→	if err != nil {
316→		return fmt.Errorf("failed to get branch entries: %w", err)
317→	}
318→
319→	basePath := trailID.Path() + "/"
320→
321→	// Remove entries for this trail
322→	found := false
323→	for path := range entries {
324→		if strings.HasPrefix(path, basePath) {
325→			delete(entries, path)
326→			found = true
327→		}
328→	}
329→	if !found {
330→		return fmt.Errorf("trail %s not found", trailID)
331→	}
332→
333→	// Build tree and commit
334→	newTreeHash, err := checkpoint.BuildTreeFromEntries(s.repo, entries)
335→	if err != nil {
336→		return fmt.Errorf("failed to build tree: %w", err)
337→	}
338→
339→	authorName, authorEmail := checkpoint.GetGitAuthorFromRepo(s.repo)
340→	commitMsg := fmt.Sprintf("Delete trail: %s", trailID)
341→	commitHash, err := s.createCommit(newTreeHash, ref.Hash(), commitMsg, authorName, authorEmail)
342→	if err != nil {
343→		return fmt.Errorf("failed to create commit: %w", err)
344→	}
345→
346→	newRef := plumbing.NewHashReference(plumbing.NewBranchReferenceName(paths.TrailsBranchName), commitHash)
347→	if err := s.repo.Storer.SetReference(newRef); err != nil {
348→		return fmt.Errorf("failed to update branch reference: %w", err)
349→	}
350→
351→	return nil
352→}
