354→// getBranchTree returns the tree for the entire/trails branch HEAD.
355→func (s *Store) getBranchTree() (*object.Tree, error) {
356→	refName := plumbing.NewBranchReferenceName(paths.TrailsBranchName)
357→	ref, err := s.repo.Reference(refName, true)
358→	if err != nil {
359→		// Try remote tracking branch
360→		remoteRefName := plumbing.NewRemoteReferenceName("origin", paths.TrailsBranchName)
361→		ref, err = s.repo.Reference(remoteRefName, true)
362→		if err != nil {
363→			return nil, fmt.Errorf("trails branch not found: %w", err)
364→		}
365→	}
366→
367→	commit, err := s.repo.CommitObject(ref.Hash())
368→	if err != nil {
369→		return nil, fmt.Errorf("failed to get commit: %w", err)
370→	}
371→
372→	tree, err := commit.Tree()
373→	if err != nil {
374→		return nil, fmt.Errorf("failed to get tree: %w", err)
375→	}
376→
377→	return tree, nil
378→}
379→
380→// getBranchEntries returns the current branch reference and a flat map of all tree entries.
381→func (s *Store) getBranchEntries() (*plumbing.Reference, map[string]object.TreeEntry, error) {
382→	refName := plumbing.NewBranchReferenceName(paths.TrailsBranchName)
383→	ref, err := s.repo.Reference(refName, true)
384→	if err != nil {
385→		return nil, nil, fmt.Errorf("trails branch not found: %w", err)
386→	}
387→
388→	commit, err := s.repo.CommitObject(ref.Hash())
389→	if err != nil {
390→		return nil, nil, fmt.Errorf("failed to get commit: %w", err)
391→	}
392→
393→	tree, err := commit.Tree()
394→	if err != nil {
395→		return nil, nil, fmt.Errorf("failed to get tree: %w", err)
396→	}
397→
398→	entries := make(map[string]object.TreeEntry)
399→	if err := checkpoint.FlattenTree(s.repo, tree, "", entries); err != nil {
400→		return nil, nil, fmt.Errorf("failed to flatten tree: %w", err)
401→	}
402→
403→	return ref, entries, nil
404→}
