 15→// TreeChange represents a single file change within a tree.
 16→// Use a nil Entry to indicate deletion.
 17→type TreeChange struct {
 18→	// Path is the full path within the tree (e.g., "src/pkg/handler.go").
 19→	Path string
 20→	// Entry is the new tree entry. Nil means delete the file at Path.
 21→	Entry *object.TreeEntry
 22→}
 23→
 24→// MergeMode controls how entries at the leaf directory are handled by UpdateSubtree.
 25→type MergeMode int
 26→
 27→const (
 28→	// ReplaceAll replaces the entire leaf directory contents with the new entries.
 29→	ReplaceAll MergeMode = iota
 30→	// MergeKeepExisting merges new entries into the existing leaf directory,
 31→	// keeping existing entries that are not overwritten (unless in DeleteNames).
 32→	MergeKeepExisting
 33→)
 34→
 35→// UpdateSubtreeOptions configures the behavior of UpdateSubtree.
 36→type UpdateSubtreeOptions struct {
 37→	// MergeMode controls how entries at the leaf directory are handled.
 38→	MergeMode MergeMode
 39→	// DeleteNames lists entry names (at the leaf directory level) to delete.
 40→	// Only applicable when MergeMode is MergeKeepExisting.
 41→	DeleteNames []string
 42→}
 43→
 44→// UpdateSubtree replaces or creates a subtree at the given path within an existing tree.
 45→// It walks the tree path, replacing only the entries along the modified path.
 46→// All sibling entries at each level retain their original hashes — no re-reading needed.
 47→//
 48→// pathSegments is the directory path split into segments (e.g., ["a3", "b2c4d5e6f7"]).
 49→// newEntries are the files/dirs to place at the leaf directory.
 50→// Returns the new root tree hash.
 51→func UpdateSubtree(
 52→	repo *git.Repository,
 53→	rootTreeHash plumbing.Hash,
 54→	pathSegments []string,
 55→	newEntries []object.TreeEntry,
 56→	opts UpdateSubtreeOptions,
 57→) (plumbing.Hash, error) {
 58→	if len(pathSegments) == 0 {
 59→		return buildLeafTree(repo, rootTreeHash, newEntries, opts)
 60→	}
 61→
 62→	// Read the current tree at this level
 63→	// Get all entries in the tree and add them to the currentEntries slice
 64→	var currentEntries []object.TreeEntry
 65→	if rootTreeHash != plumbing.ZeroHash {
 66→		tree, err := repo.TreeObject(rootTreeHash)
 67→		if err != nil {
 68→			return plumbing.ZeroHash, fmt.Errorf("failed to read tree %s: %w", rootTreeHash, err)
 69→		}
 70→		currentEntries = tree.Entries
 71→	}
 72→
 73→	targetDir := pathSegments[0]
 74→	remainingPath := pathSegments[1:]
 75→
 76→	// Find the existing subtree entry for targetDir
 77→	var existingSubtreeHash plumbing.Hash
 78→	found := false
 79→	for _, entry := range currentEntries {
 80→		if entry.Name == targetDir && entry.Mode == filemode.Dir {
 81→			existingSubtreeHash = entry.Hash
 82→			found = true
 83→			break
 84→		}
 85→	}
 86→
 87→	// Recurse into the subtree
 88→	newSubtreeHash, err := UpdateSubtree(repo, existingSubtreeHash, remainingPath, newEntries, opts)
 89→	if err != nil {
 90→		return plumbing.ZeroHash, err
 91→	}
 92→
 93→	// Build a new tree at this level with the updated subtree entry
 94→	updatedEntries := make([]object.TreeEntry, 0, len(currentEntries)+1)
 95→	replaced := false
 96→	for _, entry := range currentEntries {
 97→		if entry.Name == targetDir {
 98→			updatedEntries = append(updatedEntries, object.TreeEntry{
 99→				Name: targetDir,
100→				Mode: filemode.Dir,
101→				Hash: newSubtreeHash,
102→			})
103→			replaced = true
104→		} else {
105→			updatedEntries = append(updatedEntries, entry)
106→		}
107→	}
108→	if !found && !replaced {
109→		updatedEntries = append(updatedEntries, object.TreeEntry{
110→			Name: targetDir,
111→			Mode: filemode.Dir,
112→			Hash: newSubtreeHash,
113→		})
114→	}
115→
116→	sortTreeEntries(updatedEntries)
117→	return storeTree(repo, updatedEntries)
118→}
119→
120→// buildLeafTree builds the tree at the leaf of the UpdateSubtree path.
121→func buildLeafTree(
122→	repo *git.Repository,
123→	existingTreeHash plumbing.Hash,
124→	newEntries []object.TreeEntry,
125→	opts UpdateSubtreeOptions,
126→) (plumbing.Hash, error) {
127→	if opts.MergeMode == ReplaceAll || existingTreeHash == plumbing.ZeroHash {
128→		sorted := make([]object.TreeEntry, len(newEntries))
129→		copy(sorted, newEntries)
130→		sortTreeEntries(sorted)
131→		return storeTree(repo, sorted)
132→	}
133→
134→	// MergeKeepExisting: read existing tree, merge
135→	existingTree, err := repo.TreeObject(existingTreeHash)
136→	if err != nil {
137→		sorted := make([]object.TreeEntry, len(newEntries))
138→		copy(sorted, newEntries)
139→		sortTreeEntries(sorted)
140→		return storeTree(repo, sorted)
141→	}
142→
143→	// Build lookup of new entries by name
144→	newByName := make(map[string]object.TreeEntry, len(newEntries))
145→	for _, e := range newEntries {
146→		newByName[e.Name] = e
147→	}
148→
149→	// Build delete set
150→	deleteSet := make(map[string]bool, len(opts.DeleteNames))
151→	for _, name := range opts.DeleteNames {
152→		deleteSet[name] = true
153→	}
154→
155→	// Merge: keep existing unless overwritten or deleted
156→	merged := make([]object.TreeEntry, 0, len(existingTree.Entries)+len(newEntries))
157→	for _, existing := range existingTree.Entries {
158→		if deleteSet[existing.Name] {
159→			continue
160→		}
161→		if replacement, ok := newByName[existing.Name]; ok {
162→			merged = append(merged, replacement)
163→			delete(newByName, existing.Name)
164→		} else {
165→			merged = append(merged, existing)
166→		}
167→	}
168→	// Add remaining new entries (ones that didn't replace an existing entry)
169→	for _, e := range newEntries {
170→		if _, stillNew := newByName[e.Name]; stillNew {
171→			merged = append(merged, e)
172→		}
173→	}
174→
175→	sortTreeEntries(merged)
176→	return storeTree(repo, merged)
177→}
178→
179→// storeTree creates a git tree object from entries and stores it in the repo.
180→func storeTree(repo *git.Repository, entries []object.TreeEntry) (plumbing.Hash, error) {
181→	tree := &object.Tree{Entries: entries}
182→	obj := repo.Storer.NewEncodedObject()
183→	if err := tree.Encode(obj); err != nil {
184→		return plumbing.ZeroHash, fmt.Errorf("failed to encode tree: %w", err)
185→	}
186→	hash, err := repo.Storer.SetEncodedObject(obj)
187→	if err != nil {
188→		return plumbing.ZeroHash, fmt.Errorf("failed to store tree: %w", err)
189→	}
190→	return hash, nil
191→}
192→
193→// ApplyTreeChanges applies multiple file-level changes to a tree efficiently.
194→// Changes are grouped by directory and applied in a single recursive pass.
195→// Unchanged subdirectories retain their hashes — this is the key optimization
196→// over FlattenTree + BuildTreeFromEntries for sparse changes.
197→func ApplyTreeChanges(
198→	repo *git.Repository,
199→	rootTreeHash plumbing.Hash,
200→	changes []TreeChange,
201→) (plumbing.Hash, error) {
202→	if len(changes) == 0 {
203→		return rootTreeHash, nil
204→	}
205→
206→	// Read the current root tree
207→	var currentEntries []object.TreeEntry
208→	if rootTreeHash != plumbing.ZeroHash {
209→		tree, err := repo.TreeObject(rootTreeHash)
210→		if err != nil {
211→			return plumbing.ZeroHash, fmt.Errorf("failed to read tree: %w", err)
212→		}
213→		currentEntries = make([]object.TreeEntry, len(tree.Entries))
214→		copy(currentEntries, tree.Entries)
215→	}
216→
217→	// Group changes by first path segment
218→	type dirChanges struct {
219→		subChanges []TreeChange // Changes within this subdirectory
220→		fileChange *TreeChange  // Direct file change at this level (nil if none)
221→	}
222→	grouped := make(map[string]*dirChanges)
223→
224→	for i := range changes {
225→		c := changes[i]
226→		first, rest := splitFirstSegment(c.Path)
227→		if grouped[first] == nil {
228→			grouped[first] = &dirChanges{}
229→		}
230→		if rest == "" {
231→			cc := c
232→			grouped[first].fileChange = &cc
233→		} else {
234→			grouped[first].subChanges = append(grouped[first].subChanges, TreeChange{
235→				Path:  rest,
236→				Entry: c.Entry,
237→			})
238→		}
239→	}
240→
241→	// Build entry map for modifications
242→	entryMap := make(map[string]object.TreeEntry, len(currentEntries))
243→	for _, e := range currentEntries {
244→		entryMap[e.Name] = e
245→	}
246→
247→	// Process each group
248→	for name, dc := range grouped {
249→		if dc.fileChange != nil {
250→			if dc.fileChange.Entry == nil {
251→				delete(entryMap, name)
252→			} else {
253→				entryMap[name] = object.TreeEntry{
254→					Name: name,
255→					Mode: dc.fileChange.Entry.Mode,
256→					Hash: dc.fileChange.Entry.Hash,
257→				}
258→			}
259→		}
260→		if len(dc.subChanges) > 0 {
261→			existingHash := plumbing.ZeroHash
262→			if existing, ok := entryMap[name]; ok && existing.Mode == filemode.Dir {
263→				existingHash = existing.Hash
264→			}
265→			newSubHash, err := ApplyTreeChanges(repo, existingHash, dc.subChanges)
266→			if err != nil {
267→				return plumbing.ZeroHash, fmt.Errorf("failed to apply changes in %s: %w", name, err)
268→			}
269→			entryMap[name] = object.TreeEntry{
270→				Name: name,
271→				Mode: filemode.Dir,
272→				Hash: newSubHash,
273→			}
274→		}
275→	}
276→
277→	result := make([]object.TreeEntry, 0, len(entryMap))
278→	for _, e := range entryMap {
279→		result = append(result, e)
280→	}
281→	sortTreeEntries(result)
282→	return storeTree(repo, result)
283→}
284→
285→// splitFirstSegment splits "a/b/c" into ("a", "b/c"), and "file.txt" into ("file.txt", "").
286→func splitFirstSegment(path string) (first, rest string) {
287→	parts := strings.SplitN(path, "/", 2)
288→	if len(parts) == 1 {
289→		return parts[0], ""
290→	}
291→	return parts[0], parts[1]
292→}
