// Delete removes a trail from the entire/trails branch.
func (s *Store) Delete(trailID ID) error {
	if err := s.EnsureBranch(); err != nil {
		return fmt.Errorf("failed to ensure trails branch: %w", err)
	}

	commitHash, rootTreeHash, err := s.getBranchRef()
	if err != nil {
		return fmt.Errorf("failed to get branch ref: %w", err)
	}

	// Verify the trail exists by navigating the tree at O(depth)
	shard, suffix := trailID.ShardParts()
	if err := s.verifyTrailExists(rootTreeHash, shard, suffix); err != nil {
		return err
	}

	// Delete the trail's subtree by removing it from the shard directory
	newTreeHash, err := checkpoint.UpdateSubtree(
		s.repo, rootTreeHash,
		[]string{shard},
		nil,
		checkpoint.UpdateSubtreeOptions{
			MergeMode:   checkpoint.MergeKeepExisting,
			DeleteNames: []string{suffix},
		},
	)
	if err != nil {
		return fmt.Errorf("failed to update subtree: %w", err)
	}

	authorName, authorEmail := checkpoint.GetGitAuthorFromRepo(s.repo)
	commitMsg := fmt.Sprintf("Delete trail: %s", trailID)
	newCommitHash, err := checkpoint.CreateCommit(s.repo, newTreeHash, commitHash, commitMsg, authorName, authorEmail)
	if err != nil {
		return fmt.Errorf("failed to create commit: %w", err)
	}

	newRef := plumbing.NewHashReference(plumbing.NewBranchReferenceName(paths.TrailsBranchName), newCommitHash)
	if err := s.repo.Storer.SetReference(newRef); err != nil {
		return fmt.Errorf("failed to update branch reference: %w", err)
	}

	return nil
}

// verifyTrailExists checks that a trail subtree exists at shard/suffix within the root tree.
func (s *Store) verifyTrailExists(rootTreeHash plumbing.Hash, shard, suffix string) error {
	rootTree, err := s.repo.TreeObject(rootTreeHash)
	if err != nil {
		return fmt.Errorf("trail %s%s not found", shard, suffix)
	}

	shardEntry, err := rootTree.FindEntry(shard)
	if err != nil {
		return fmt.Errorf("trail %s%s not found", shard, suffix)
	}

	shardTree, err := s.repo.TreeObject(shardEntry.Hash)
	if err != nil {
		return fmt.Errorf("trail %s%s not found", shard, suffix)
	}

	if _, err := shardTree.FindEntry(suffix); err != nil {
		return fmt.Errorf("trail %s%s not found", shard, suffix)
	}

	return nil
}

