219→// FindByBranch finds a trail for the given branch name.
220→// Returns (nil, nil) if no trail exists for the branch.
221→func (s *Store) FindByBranch(branchName string) (*Metadata, error) {
222→	trails, err := s.List()
223→	if err != nil {
224→		return nil, err
225→	}
226→
227→	for _, t := range trails {
228→		if t.Branch == branchName {
229→			return t, nil
230→		}
231→	}
232→	return nil, nil //nolint:nilnil // nil, nil means "not found" — callers check both
233→}
