235→// List returns all trail metadata from the entire/trails branch.
236→func (s *Store) List() ([]*Metadata, error) {
237→	tree, err := s.getBranchTree()
238→	if err != nil {
239→		// Branch doesn't exist yet — no trails
240→		return nil, nil //nolint:nilerr // Expected when no trails exist yet
241→	}
242→
243→	var trails []*Metadata
244→	entries := make(map[string]object.TreeEntry)
245→	if err := checkpoint.FlattenTree(s.repo, tree, "", entries); err != nil {
246→		return nil, fmt.Errorf("failed to flatten tree: %w", err)
247→	}
248→
249→	// Find all metadata.json files
250→	for path, entry := range entries {
251→		if !strings.HasSuffix(path, "/"+metadataFile) {
252→			continue
253→		}
254→
255→		blob, err := s.repo.BlobObject(entry.Hash)
256→		if err != nil {
257→			continue
258→		}
259→		reader, err := blob.Reader()
260→		if err != nil {
261→			continue
262→		}
263→
264→		var metadata Metadata
265→		decodeErr := json.NewDecoder(reader).Decode(&metadata)
266→		_ = reader.Close()
267→		if decodeErr != nil {
268→			continue
269→		}
270→
271→		trails = append(trails, &metadata)
272→	}
273→
274→	return trails, nil
275→}
