277→// Update updates an existing trail's metadata. It reads the current metadata,
278→// applies the provided update function, and writes it back.
279→func (s *Store) Update(trailID ID, updateFn func(*Metadata)) error {
280→	if err := ValidateID(string(trailID)); err != nil {
281→		return err
282→	}
283→
284→	metadata, discussion, checkpoints, err := s.Read(trailID)
285→	if err != nil {
286→		return fmt.Errorf("failed to read trail for update: %w", err)
287→	}
288→
289→	updateFn(metadata)
290→	metadata.UpdatedAt = time.Now()
291→
292→	return s.Write(metadata, discussion, checkpoints)
293→}
