295→// AddCheckpoint prepends a checkpoint reference to a trail's checkpoints list (newest first).
296→// Only reads and writes the checkpoints.json file — metadata and discussion are untouched.
297→func (s *Store) AddCheckpoint(trailID ID, ref CheckpointRef) error {
298→	if err := ValidateID(string(trailID)); err != nil {
299→		return err
300→	}
301→
302→	if err := s.EnsureBranch(); err != nil {
303→		return fmt.Errorf("failed to ensure trails branch: %w", err)
304→	}
305→
306→	commitHash, rootTreeHash, err := s.getBranchRef()
307→	if err != nil {
308→		return fmt.Errorf("failed to get branch ref: %w", err)
309→	}
310→
311→	// Navigate to the trail's subtree and read only checkpoints.json
312→	shard, suffix := trailID.ShardParts()
313→	checkpoints, err := s.readCheckpointsFromTree(rootTreeHash, shard, suffix)
314→	if err != nil {
315→		return fmt.Errorf("failed to read checkpoints for trail %s: %w", trailID, err)
316→	}
317→
318→	// Prepend new ref (newest first)
319→	checkpoints.Checkpoints = append(checkpoints.Checkpoints, CheckpointRef{})
320→	copy(checkpoints.Checkpoints[1:], checkpoints.Checkpoints[:len(checkpoints.Checkpoints)-1])
321→	checkpoints.Checkpoints[0] = ref
322→
323→	// Create new blob and splice back — MergeKeepExisting preserves metadata.json and discussion.json
324→	checkpointsJSON, err := json.MarshalIndent(checkpoints, "", "  ")
325→	if err != nil {
326→		return fmt.Errorf("failed to marshal checkpoints: %w", err)
327→	}
328→	blobHash, err := checkpoint.CreateBlobFromContent(s.repo, checkpointsJSON)
329→	if err != nil {
330→		return fmt.Errorf("failed to create checkpoints blob: %w", err)
331→	}
332→
333→	newTreeHash, err := checkpoint.UpdateSubtree(
334→		s.repo, rootTreeHash,
335→		[]string{shard, suffix},
336→		[]object.TreeEntry{{Name: checkpointsFile, Mode: filemode.Regular, Hash: blobHash}},
337→		checkpoint.UpdateSubtreeOptions{MergeMode: checkpoint.MergeKeepExisting},
338→	)
339→	if err != nil {
340→		return fmt.Errorf("failed to update subtree: %w", err)
341→	}
342→
343→	authorName, authorEmail := checkpoint.GetGitAuthorFromRepo(s.repo)
344→	commitMsg := fmt.Sprintf("Add checkpoint to trail: %s", trailID)
345→	newCommitHash, err := checkpoint.CreateCommit(s.repo, newTreeHash, commitHash, commitMsg, authorName, authorEmail)
346→	if err != nil {
347→		return fmt.Errorf("failed to create commit: %w", err)
348→	}
349→
350→	newRef := plumbing.NewHashReference(plumbing.NewBranchReferenceName(paths.TrailsBranchName), newCommitHash)
351→	if err := s.repo.Storer.SetReference(newRef); err != nil {
352→		return fmt.Errorf("failed to update branch reference: %w", err)
353→	}
354→
355→	return nil
356→}
