358→// readCheckpointsFromTree navigates to a trail's subtree and reads only checkpoints.json.
359→func (s *Store) readCheckpointsFromTree(rootTreeHash plumbing.Hash, shard, suffix string) (*Checkpoints, error) {
360→	rootTree, err := s.repo.TreeObject(rootTreeHash)
361→	if err != nil {
362→		return nil, fmt.Errorf("trail %s%s not found", shard, suffix)
363→	}
364→
365→	shardEntry, err := rootTree.FindEntry(shard)
366→	if err != nil {
367→		return nil, fmt.Errorf("trail %s%s not found", shard, suffix)
368→	}
369→
370→	shardTree, err := s.repo.TreeObject(shardEntry.Hash)
371→	if err != nil {
372→		return nil, fmt.Errorf("trail %s%s not found", shard, suffix)
373→	}
374→
375→	trailEntry, err := shardTree.FindEntry(suffix)
376→	if err != nil {
377→		return nil, fmt.Errorf("trail %s%s not found", shard, suffix)
378→	}
379→
380→	trailTree, err := s.repo.TreeObject(trailEntry.Hash)
381→	if err != nil {
382→		return nil, fmt.Errorf("trail %s%s not found", shard, suffix)
383→	}
384→
385→	var checkpoints Checkpoints
386→	cpEntry, err := trailTree.FindEntry(checkpointsFile)
387→	if err != nil {
388→		// No checkpoints file yet — return empty
389→		return &Checkpoints{Checkpoints: []CheckpointRef{}}, nil
390→	}
391→
392→	blob, err := s.repo.BlobObject(cpEntry.Hash)
393→	if err != nil {
394→		return &Checkpoints{Checkpoints: []CheckpointRef{}}, nil
395→	}
396→
397→	reader, err := blob.Reader()
398→	if err != nil {
399→		return &Checkpoints{Checkpoints: []CheckpointRef{}}, nil
400→	}
401→	defer reader.Close()
402→
403→	if err := json.NewDecoder(reader).Decode(&checkpoints); err != nil {
404→		return &Checkpoints{Checkpoints: []CheckpointRef{}}, nil
405→	}
406→
407→	return &checkpoints, nil
408→}
409→
410→// Delete removes a trail from the entire/trails branch.
411→func (s *Store) Delete(trailID ID) error {
412→	if err := ValidateID(string(trailID)); err != nil {
413→		return err
414→	}
415→
416→	if err := s.EnsureBranch(); err != nil {
417→		return fmt.Errorf("failed to ensure trails branch: %w", err)
418→	}
419→
420→	commitHash, rootTreeHash, err := s.getBranchRef()
421→	if err != nil {
422→		return fmt.Errorf("failed to get branch ref: %w", err)
423→	}
424→
425→	// Verify the trail exists by navigating the tree at O(depth)
426→	shard, suffix := trailID.ShardParts()
427→	if err := s.verifyTrailExists(rootTreeHash, shard, suffix); err != nil {
428→		return err
429→	}
430→
431→	// Delete the trail's subtree by removing it from the shard directory
432→	newTreeHash, err := checkpoint.UpdateSubtree(
433→		s.repo, rootTreeHash,
434→		[]string{shard},
435→		nil,
436→		checkpoint.UpdateSubtreeOptions{
437→			MergeMode:   checkpoint.MergeKeepExisting,
438→			DeleteNames: []string{suffix},
439→		},
440→	)
441→	if err != nil {
442→		return fmt.Errorf("failed to update subtree: %w", err)
443→	}
444→
445→	authorName, authorEmail := checkpoint.GetGitAuthorFromRepo(s.repo)
446→	commitMsg := fmt.Sprintf("Delete trail: %s", trailID)
447→	newCommitHash, err := checkpoint.CreateCommit(s.repo, newTreeHash, commitHash, commitMsg, authorName, authorEmail)
448→	if err != nil {
449→		return fmt.Errorf("failed to create commit: %w", err)
450→	}
451→
452→	newRef := plumbing.NewHashReference(plumbing.NewBranchReferenceName(paths.TrailsBranchName), newCommitHash)
453→	if err := s.repo.Storer.SetReference(newRef); err != nil {
454→		return fmt.Errorf("failed to update branch reference: %w", err)
455→	}
456→
457→	return nil
458→}
459→
460→// verifyTrailExists checks that a trail subtree exists at shard/suffix within the root tree.
461→func (s *Store) verifyTrailExists(rootTreeHash plumbing.Hash, shard, suffix string) error {
462→	rootTree, err := s.repo.TreeObject(rootTreeHash)
463→	if err != nil {
464→		return fmt.Errorf("trail %s%s not found", shard, suffix)
465→	}
466→
467→	shardEntry, err := rootTree.FindEntry(shard)
468→	if err != nil {
469→		return fmt.Errorf("trail %s%s not found", shard, suffix)
470→	}
471→
472→	shardTree, err := s.repo.TreeObject(shardEntry.Hash)
473→	if err != nil {
474→		return fmt.Errorf("trail %s%s not found", shard, suffix)
475→	}
476→
477→	if _, err := shardTree.FindEntry(suffix); err != nil {
478→		return fmt.Errorf("trail %s%s not found", shard, suffix)
479→	}
480→
481→	return nil
482→}
483→
484→// getBranchRef returns the commit hash and root tree hash for the entire/trails branch HEAD
485→// without flattening the tree. Falls back to remote tracking branch if local is missing.
486→func (s *Store) getBranchRef() (commitHash, rootTreeHash plumbing.Hash, err error) {
487→	refName := plumbing.NewBranchReferenceName(paths.TrailsBranchName)
488→	ref, refErr := s.repo.Reference(refName, true)
489→	if refErr != nil {
490→		// Try remote tracking branch
491→		remoteRefName := plumbing.NewRemoteReferenceName("origin", paths.TrailsBranchName)
492→		ref, refErr = s.repo.Reference(remoteRefName, true)
493→		if refErr != nil {
494→			return plumbing.ZeroHash, plumbing.ZeroHash, fmt.Errorf("trails branch not found: %w", refErr)
495→		}
496→	}
497→
498→	commit, err := s.repo.CommitObject(ref.Hash())
499→	if err != nil {
500→		return plumbing.ZeroHash, plumbing.ZeroHash, fmt.Errorf("failed to get commit: %w", err)
501→	}
502→
503→	return ref.Hash(), commit.TreeHash, nil
504→}
505→
506→// getBranchTree returns the tree for the entire/trails branch HEAD.
507→func (s *Store) getBranchTree() (*object.Tree, error) {
508→	_, rootTreeHash, err := s.getBranchRef()
509→	if err != nil {
510→		return nil, err
511→	}
512→
513→	tree, err := s.repo.TreeObject(rootTreeHash)
514→	if err != nil {
515→		return nil, fmt.Errorf("failed to get tree: %w", err)
516→	}
517→
518→	return tree, nil
519→}
520→
521→// createCommit creates a commit on the trails branch.
522→func (s *Store) createCommit(treeHash, parentHash plumbing.Hash, message, authorName, authorEmail string) (plumbing.Hash, error) {
523→	return checkpoint.CreateCommit(s.repo, treeHash, parentHash, message, authorName, authorEmail)
524→}
