114→// buildTrailEntries creates blob objects for a trail's 3 files and returns them as tree entries.
115→func (s *Store) buildTrailEntries(metadata *Metadata, discussion *Discussion, checkpoints *Checkpoints) ([]object.TreeEntry, error) {
116→	if discussion == nil {
117→		discussion = &Discussion{Comments: []Comment{}}
118→	}
119→	if checkpoints == nil {
120→		checkpoints = &Checkpoints{Checkpoints: []CheckpointRef{}}
121→	}
