123→	type fileSpec struct {
124→		name string
125→		data any
126→	}
127→	files := []fileSpec{
128→		{metadataFile, metadata},
129→		{discussionFile, discussion},
130→		{checkpointsFile, checkpoints},
131→	}
132→
133→	entries := make([]object.TreeEntry, 0, len(files))
134→	for _, f := range files {
135→		jsonBytes, err := json.MarshalIndent(f.data, "", "  ")
136→		if err != nil {
137→			return nil, fmt.Errorf("failed to marshal %s: %w", f.name, err)
138→		}
