140→		if err != nil {
141→			return nil, fmt.Errorf("failed to create %s blob: %w", f.name, err)
142→		}
143→		entries = append(entries, object.TreeEntry{
144→			Name: f.name,
145→			Mode: filemode.Regular,
146→			Hash: blobHash,
147→		})
148→	}
149→
150→	return entries, nil
151→}
