153→// Read reads a trail by its ID from the entire/trails branch.
154→func (s *Store) Read(trailID ID) (*Metadata, *Discussion, *Checkpoints, error) {
155→	if err := ValidateID(string(trailID)); err != nil {
156→		return nil, nil, nil, err
157→	}
158→
159→	tree, err := s.getBranchTree()
160→	if err != nil {
161→		return nil, nil, nil, err
162→	}
