164→	basePath := trailID.Path() + "/"
165→
166→	// Read metadata
167→	metadataEntry, err := tree.FindEntry(basePath + metadataFile)
168→	if err != nil {
169→		return nil, nil, nil, fmt.Errorf("trail %s not found: %w", trailID, err)
170→	}
171→	metadataBlob, err := s.repo.BlobObject(metadataEntry.Hash)
172→	if err != nil {
173→		return nil, nil, nil, fmt.Errorf("failed to read metadata blob: %w", err)
174→	}
175→	metadataReader, err := metadataBlob.Reader()
176→	if err != nil {
177→		return nil, nil, nil, fmt.Errorf("failed to open metadata reader: %w", err)
178→	}
179→	defer metadataReader.Close()
180→
181→	var metadata Metadata
182→	if err := json.NewDecoder(metadataReader).Decode(&metadata); err != nil {
183→		return nil, nil, nil, fmt.Errorf("failed to decode metadata: %w", err)
184→	}
185→
186→	// Read discussion (optional, may not exist yet)
187→	var discussion Discussion
188→	discussionEntry, err := tree.FindEntry(basePath + discussionFile)
189→	if err == nil {
190→		discussionBlob, blobErr := s.repo.BlobObject(discussionEntry.Hash)
191→		if blobErr == nil {
192→			discussionReader, readerErr := discussionBlob.Reader()
193→			if readerErr == nil {
194→				//nolint:errcheck,gosec // best-effort decode of optional discussion
195→				json.NewDecoder(discussionReader).Decode(&discussion)
196→				_ = discussionReader.Close()
197→			}
198→		}
199→	}
200→
201→	// Read checkpoints (optional, may not exist yet)
202→	var checkpoints Checkpoints
203→	checkpointsEntry, err := tree.FindEntry(basePath + checkpointsFile)
204→	if err == nil {
205→		checkpointsBlob, blobErr := s.repo.BlobObject(checkpointsEntry.Hash)
206→		if blobErr == nil {
207→			checkpointsReader, readerErr := checkpointsBlob.Reader()
208→			if readerErr == nil {
209→				//nolint:errcheck,gosec // best-effort decode of optional checkpoints
210→				json.NewDecoder(checkpointsReader).Decode(&checkpoints)
211→				_ = checkpointsReader.Close()
212→			}
213→		}
214→	}
215→
216→	return &metadata, &discussion, &checkpoints, nil
