410→// Delete removes a trail from the entire/trails branch.
411→func (s *Store) Delete(trailID ID) error {
412→	if err := ValidateID(string(trailID)); err != nil {
413→		return err
414→	}
415→
416→	if err := s.EnsureBranch(); err != nil {
417→		return fmt.Errorf("failed to ensure trails branch: %w", err)
418→	}
419→
420→	commitHash, rootTreeHash, err := s.getBranchRef()
421→	if err != nil {
422→		return fmt.Errorf("failed to get branch ref: %w", err)
423→	}
424→
425→	// Verify the trail exists by navigating the tree at O(depth)
426→	shard, suffix := trailID.ShardParts()
427→	if err := s.verifyTrailExists(rootTreeHash, shard, suffix); err != nil {
428→		return err
429→	}
430→
431→	// Delete the trail's subtree by removing it from the shard directory
432→	newTreeHash, err := checkpoint.UpdateSubtree(
433→		s.repo, rootTreeHash,
434→		[]string{shard},
435→		nil,
436→		checkpoint.UpdateSubtreeOptions{
437→			MergeMode:   checkpoint.MergeKeepExisting,
438→			DeleteNames: []string{suffix},
439→		},
440→	)
441→	if err != nil {
442→		return fmt.Errorf("failed to update subtree: %w", err)
443→	}
444→
445→	authorName, authorEmail := checkpoint.GetGitAuthorFromRepo(s.repo)
446→	commitMsg := fmt.Sprintf("Delete trail: %s", trailID)
447→	newCommitHash, err := checkpoint.CreateCommit(s.repo, newTreeHash, commitHash, commitMsg, authorName, authorEmail)
448→	if err != nil {
449→		return fmt.Errorf("failed to create commit: %w", err)
450→	}
451→
452→	newRef := plumbing.NewHashReference(plumbing.NewBranchReferenceName(paths.TrailsBranchName), newCommitHash)
453→	if err := s.repo.Storer.SetReference(newRef); err != nil {
454→		return fmt.Errorf("failed to update branch reference: %w", err)
455→	}
456→
457→	return nil
458→}
